function sumsUsingEachOnce(items: number[], target: number): number[][] {
  const seen = new Map<string, number[]>();
  for (let mask = 0; mask < 1 << items.length; mask++) {
    const s = items.filter((_, i) => (mask >> i) & 1);
    if (s.reduce((a, b) => a + b, 0) !== target) continue;
    s.sort((a, b) => a - b);
    seen.set(s.join(","), s);
  }
  return [...seen.values()];
}

