class Solution:
    def sumsUsingEachOnce(self, items: List[int], target: int) -> List[List[int]]:
        seen = set()
        for mask in range(1 << len(items)):
            s = [x for i, x in enumerate(items) if mask >> i & 1]
            if sum(s) == target:
                seen.add(tuple(sorted(s)))
        return [list(s) for s in seen]

