function sumsUsingEachOnce(items: number[], target: number): number[][] {
  const a = [...items].sort((x, y) => x - y);
  const out: number[][] = [];
  const cur: number[] = [];
  const go = (start: number, left: number): void => {
    if (left === 0) { out.push([...cur]); return; }
    for (let i = start; i < a.length; i++) {
      if (i > start && a[i] === a[i - 1]) continue; // same value as a sibling already tried
      if (a[i] > left) break;                       // sorted: the rest are too big too
      cur.push(a[i]);
      go(i + 1, left - a[i]);                       // each position at most once
      cur.pop();
    }
  };
  go(0, target);
  return out;
}

